base.r/main.tf:
terraform {
  backend "s3" {}
}
variable "environment_name" {
  type = string
}
module "app_config" {
  source = "../app-config"
}
locals {
  environment_config = module.app_config.environment_configs[var.environment_name]
  database_config    = local.environment_config.database_config
}
data "aws_vpc" "network" {
  tags = {
    network_name = local.environment_config.network_name
  }
}
resource "aws_rds_cluster" "db" {
  cluster_identifier = local.database_config.cluster_name
  engine             = "aurora-postgresql"
  vpc_security_group_ids = [data.aws_vpc.network.id]
}

base.app-config/main.tf:
locals {
  environment_configs = {
    dev  = module.dev_config
    prod = module.prod_config
  }
}
module "dev_config" {
  source       = "./env-config"
  cluster_name = "app-dev"
  network      = "dev"
  feature      = "1"
}
module "prod_config" {
  source       = "./env-config"
  cluster_name = "app-prod"
  network      = "prod"
  feature      = "1"
}
output "environment_configs" {
  value = local.environment_configs
}

base.app-config/env-config/main.tf:
variable "cluster_name" {
  type = string
}
variable "network" {
  type = string
}
variable "feature" {
  type = string
}
output "database_config" {
  value = { cluster_name = var.cluster_name, region = "us-east-1" }
}
output "network_name" {
  value = var.network
}
output "service_config" {
  value = { env = { FEATURE = var.feature } }
}

